//  EvaluationService.ts
//  Evaluation tab-க்கு தேவையான எல்லா SP API calls இங்கே மட்டும்
//  Import: EvaluationConfig மட்டும் — main Config.ts இல்லை
// ═══════════════════════════════════════════════════════════════════════════

import moment from "moment";
import {
  CommonServices,
  getVRRDetails,
  InterviewServices,
} from "../../Services/ServiceExport";

import {
  EvalListNames,
  EvalStatusId,
  EvalInterviewLevels,
  EvalUIConfig,
} from "../config/EvaluationConfig";

import { InterviewPanaldata } from "../../Models/Screens";
import {
  EvaluationCandidate,
  IEvaluationService,
  ScoreSheetResult,
  TooltipEntry,
} from "./IEvaluationService";

// ─────────────────────────────────────────────────────────────────────────────

export class EvaluationService implements IEvaluationService {

  // ── 1. SP user numeric ID ─────────────────────────────────────────────────
  //  CommonServices.getUserGuidByEmail → sp.web.siteUsers.getByEmail(email)
  //  Returns: { key: user.Id, text: user.Title }
  async getCurrentUserGuid(email: string): Promise<string | null> {
    try {
      const res = await CommonServices.getUserGuidByEmail(email);
      return res.status === 200 && res.data?.key
        ? String(res.data.key)
        : null;
    } catch (e) {
      console.error("EvaluationService.getCurrentUserGuid:", e);
      return null;
    }
  }

  // ── 2. Interview panels assigned to this user ─────────────────────────────
  //  List : EvalListNames.HRMSInterviewPanelDetails
  //  Filter: InterviewPanelId eq userGuid
  async getInterviewPanelsByUser(userGuid: string): Promise<InterviewPanaldata[]> {
    try {
      const res = await InterviewServices.GetInterviewPanelDetails([
        { FilterKey: "InterviewPanelId", Operator: "eq", FilterValue: userGuid },
      ]);
      return res.data ?? [];
    } catch (e) {
      console.error("EvaluationService.getInterviewPanelsByUser:", e);
      return [];
    }
  }

  // ── 3. Combined candidate + position details ──────────────────────────────
  //  List  : EvalListNames.HRMSCandidatePersonalDetails
  //  Filter: StatusId in [16, 20]
  //          ItemCreated eq "No"
  //          ID in candidateIDs
  async getCombinedCandidates(
    candidateIDs: number[],
    employeeList: any[]
  ): Promise<any[]> {
    try {
      const res = await InterviewServices.GetCombinedCandidatePositionDetails(
        [
          {
            FilterKey:   "StatusId",
            Operator:    "in",
            FilterValue: [
              EvalStatusId.InterviewScheduled,
              EvalStatusId.InterviewScheduledforLevel2,
            ],
          },
          {
            FilterKey:   "ItemCreated",
            Operator:    "eq",
            FilterValue: EvalUIConfig.ItemCreatedNo,
          },
          {
            FilterKey:   "ID",
            Operator:    "in",
            FilterValue: candidateIDs,
          },
        ],
        "and",
        employeeList
      );
      return res.data ?? [];
    } catch (e) {
      console.error("EvaluationService.getCombinedCandidates:", e);
      return [];
    }
  }

  // ── 4. PatersonGrade + Level for one recruitment record ───────────────────
  //  List 1: EvalListNames.HRMSRecruitmentDptDetails → PatersonGrade, JobCodeId
  //  List 2: EvalListNames.HRMSGradeMaster           → Level
  async getGradeAndLevel(
    recruitmentID: number
  ): Promise<{ grade: string; level: string; jobCodeID: number }> {
    let grade = ""; let level = ""; let jobCodeID = 0;
    try {
      const vrrRes = await getVRRDetails.GetRecruitmentDetails(
        [{ FilterKey: "ID", Operator: "eq", FilterValue: recruitmentID }],
        ""
      );
      jobCodeID = vrrRes?.data?.[0]?.JobCodeId     ?? 0;
      grade     = vrrRes?.data?.[0]?.PatersonGrade ?? "";
      if (grade) {
        const gradeRes = await CommonServices.GetGradeLevel(grade);
        level = gradeRes?.data?.[0]?.Level ?? "";
      }
    } catch (e) {
      console.warn("EvaluationService.getGradeAndLevel recruitmentID:", recruitmentID, e);
    }
    return { grade, level, jobCodeID };
  }

  // ── 5. ON-DEMAND — Hover tooltip ──────────────────────────────────────────
  //  List  : EvalListNames.HRMSInterviewPanelDetails
  //  Filter: CandidateID/Id eq candidateID, InterviewLevel eq level
  //  Returns: [{ Key: panelMemberName, Value: "Completed" | "Pending" }]
  //  Called ONLY when user hovers status dot — never on mount
  async getTooltipData(
    candidateID: number,
    interviewLevel: string
  ): Promise<TooltipEntry[]> {
    try {
      const res = await getVRRDetails.GetEvalutionActionData([
        { FilterKey: "CandidateID/Id", Operator: "eq", FilterValue: candidateID },
        { FilterKey: "InterviewLevel",  Operator: "eq", FilterValue: interviewLevel },
      ]);
      return (res.data as TooltipEntry[]) ?? [];
    } catch (e) {
      console.error("EvaluationService.getTooltipData:", e);
      return [];
    }
  }

  // ── 6. ON-DEMAND — Score sheet already uploaded check ─────────────────────
  //  List  : EvalListNames.HRMSInterviewPanelDetails (via GetMasterData)
  //  Logic : InterviewPanelList.tsx → checkIsScoreSheetUploaded (line 272–358)
  //  Called ONLY when user clicks the Evaluate (view) icon — never on mount
  async checkScoreSheet(
    candidateID: number,
    statusId:    number | string,
    userEmail:   string
  ): Promise<ScoreSheetResult> {
    try {
      const [panelRes, userRes] = await Promise.all([
        CommonServices.GetMasterData(EvalListNames.HRMSInterviewPanelDetails),
        CommonServices.getUserGuidByEmail(userEmail),
      ]);

      const currentUserKey = userRes.data?.key?.toString();
      if (!currentUserKey) return { canProceed: true };

      const allPanels: any[] = panelRes?.data ?? [];

      // 1. Filter by this candidate
      const candidatePanels = allPanels.filter(
        (panel) => panel.CandidateIDId?.toString() === candidateID.toString()
      );
      if (!candidatePanels.length) return { canProceed: true };

      // 2. Filter by current user
      const userPanels = candidatePanels.filter((panel) =>
        panel.InterviewPanelStringId?.includes(currentUserKey)
      );
      if (!userPanels.length) return { canProceed: true };

      // 3. Determine target level (same as InterviewPanelList line 309/332)
      if (statusId === EvalStatusId.InterviewScheduled) {
        const levelFiltered = userPanels.filter(
          (p) => p.InterviewLevel === EvalInterviewLevels.Level1
        );
        const alreadyUploaded = levelFiltered.some(
          (p) => p.IsScoreSheetUploaded === EvalUIConfig.ScoreSheetUploadedValue
        );
        return alreadyUploaded
          ? { canProceed: false, level: EvalInterviewLevels.Level1 }
          : { canProceed: true };
      }

      if (statusId === EvalStatusId.InterviewScheduledforLevel2) {
        const levelFiltered = userPanels.filter(
          (p) => p.InterviewLevel === EvalInterviewLevels.Level2
        );
        const alreadyUploaded = levelFiltered.some(
          (p) => p.IsScoreSheetUploaded === EvalUIConfig.ScoreSheetUploadedValue
        );
        return alreadyUploaded
          ? { canProceed: false, level: EvalInterviewLevels.Level2 }
          : { canProceed: true };
      }

      return { canProceed: true };
    } catch (e) {
      console.error("EvaluationService.checkScoreSheet:", e);
      return { canProceed: true };
    }
  }

  // ── Static helper: build typed EvaluationCandidate from raw data ──────────
  //  Logic: InterviewPanelList.tsx enrichedCandidates map (line 463–529)
  static buildRow(
    candidate: any,
    grade:     string,
    level:     string,
    jobCodeID: number
  ): EvaluationCandidate {
    const rawDate = candidate?.InterviewDateLevel2 || candidate?.InterviewDate || "";
    const rawTime = candidate?.InterviewTimeLevel2 || candidate?.InterviewTime || "";

    const interviewDateTime = moment(
      `${rawDate} ${rawTime}`,
      EvalUIConfig.InterviewDateParseFormat
    ).format(EvalUIConfig.InterviewDateDisplayFormat);

    return {
      id:            candidate.ID,
      applicantName: `${candidate.FristName ?? ""} ${candidate.LastName ?? ""}`.trim(),
      positionTitle: candidate.PositionTitle ?? "",
      interviewDate: rawDate,
      interviewDateTime,
      interviewLevel:
        level === EvalInterviewLevels.Level2
          ? EvalInterviewLevels.Levels2
          : level,
      grade,
      gradeLabel:    "",
      attachments:   candidate.CandidateCVDoc?.length ?? 0,
      status:        candidate.Status    ?? "",
      statusId:      candidate.StatusId  ?? "",
      recruitmentID: candidate.RecruitmentID ?? "",
      jobCodeID,
    };
  }
}

// Singleton — import this one instance everywhere
export const evaluationService = new EvaluationService();
